const started = $('Prepare synthetic evaluation prompt').item.json;
const content = $json.choices?.[0]?.message?.content;
if (typeof content !== 'string' || !content.trim()) throw new Error('IA: NVIDIA retornou conteúdo vazio');
let result;
try { result = JSON.parse(content); } catch (error) { throw new Error('VALIDAÇÃO: JSON inválido: ' + error.message); }
if (!result || !Array.isArray(result.achados) || result.achados.length < 1) throw new Error('VALIDAÇÃO: nenhum achado sintético foi extraído');
const source = started.synthetic_document;
for (const finding of result.achados) {
  if (!finding || typeof finding !== 'object' || Number(finding.pagina) !== 1 || !String(finding.evidencia || '').trim() || !source.includes(String(finding.evidencia).trim())) throw new Error('VALIDAÇÃO: página ou evidência não corresponde ao fixture sintético');
  if (!String(finding.fato || '').trim()) throw new Error('VALIDAÇÃO: fato do achado está vazio');
}
return [{ json: {
  provider: 'NVIDIA NIM API Trial',
  model: 'openai/gpt-oss-20b',
  latency_ms: Date.now() - Number(started.request_started_at_ms),
  input_tokens: Number($json.usage?.prompt_tokens || 0),
  output_tokens: Number($json.usage?.completion_tokens || 0),
  findings_count: result.achados.length,
  citation_validation: 'passou no fixture sintético',
  findings: result.achados
} }];
